'use strict';

// MODULES //

var tape = require( 'tape' );
var ctor = require( './../lib' );


// TESTS //

tape( 'main export is a function', function test( t ) {
	t.ok( true, __filename );
	t.strictEqual( typeof ctor, 'function', 'main export is a function' );
	t.end();
});

tape( 'an instance throws an error if provided an invalid `colors` value', function test( t ) {
	var values;
	var i;

	values = [
		5,
		NaN,
		null,
		void 0,
		true,
		false,
		{},
		[ 5 ],
		[ 'beep', 5 ],
		function noop() {}
	];

	for ( i = 0; i < values.length; i++ ) {
		t.throws( badValue( values[i] ), TypeError, 'throws an error when provided '+values[i] );
	}
	t.end();

	function badValue( value ) {
		return function badValue() {
			var chart = ctor();
			chart.colors = value;
		};
	}
});

tape( 'an instance supports setting and getting the property value', function test( t ) {
	var chart;

	chart = ctor({
		'colors': [ 'red', 'blue' ]
	});
	t.deepEqual( chart.colors, [ 'red', 'blue' ], 'returns expected value' );

	chart.colors = [ 'green' ];
	t.deepEqual( chart.colors, [ 'green' ], 'returns expected value' );

	t.end();
});

tape( 'an instance coerces a string value to an array containing a single value', function test( t ) {
	var chart;

	chart = ctor({
		'colors': 'red'
	});
	t.deepEqual( chart.colors, [ 'red' ], 'returns expected value' );

	chart.colors = 'blue';
	t.deepEqual( chart.colors, [ 'blue' ], 'returns expected value' );

	t.end();
});

tape( 'an instance performs a defensive copy of a provided array', function test( t ) {
	var chart;
	var arr;

	arr = [ 'red', 'blue' ];
	chart = ctor({
		'colors': arr
	});
	t.notEqual( chart.colors, arr, 'returns a copy' );
	t.deepEqual( chart.colors, arr, 'returns expected value' );

	arr.push( 'green' );
	t.deepEqual( chart.colors, [ 'red', 'blue' ], 'returns expected value' );

	t.end();
});

tape( 'setting the property updates the color scale range', function test( t ) {
	var chart = ctor();

	chart.colors = [ 'red', 'blue' ];
	t.deepEqual( chart.colorScale.range, [ 'red', 'blue' ], 'returns expected value' );

	chart.colors = 'green';
	t.deepEqual( chart.colorScale.range, [ 'green' ], 'returns expected value' );

	t.end();
});

tape( 'setting the `colors` property to a new value triggers a `change` event', function test( t ) {
	var chart;

	chart = ctor({
		'colors': [ 'red' ]
	});

	chart.on( 'change', onChange );
	chart.colors = [ 'blue' ];

	function onChange() {
		t.ok( true, 'triggers event' );
		t.end();
	}
});

tape( 'setting the `colors` property to its current value does not trigger a `change` event', function test( t ) {
	var chart;

	chart = ctor({
		'colors': [ 'red' ]
	});

	chart.on( 'change', onChange );
	chart.colors = [ 'red' ];
	chart.colors = 'red';

	t.ok( true, 'does not trigger event' );
	t.end();

	function onChange() {
		t.ok( false, 'should not trigger event' );
	}
});
